            pitTable.position.set(-7, fy, -5);
            buildingGroup.add(pitTable);
            var pitSpots = [
                ["pit_N", -7, -6.6, 0],
                ["pit_S", -7, -3.4, Math.PI],
                ["pit_E", -5.4, -5, -Math.PI / 2],
                ["pit_W", -8.6, -5, Math.PI / 2]
            ];
            for (var pi = 0; pi < pitSpots.length; pi++) {
                var ps = pitSpots[pi];
