            addStand("pit_center", 0);
            link("pit_center", "hallNW");
            link("pit_center", "pit_N"); link("pit_center", "pit_S");
            link("pit_center", "pit_E"); link("pit_center", "pit_W");

            // two water coolers
            var wcFront = buildWaterCoolerMesh();
            wcFront.position.set(10.2, fy, 2.5);
